WITH base AS (SELECT s.grade, s.width_in AS slice, s.target, s.feet, s.gross, s.rejects, (s.seconds - s.stop_seconds) / 60 AS run_min, s.feet / ((s.seconds - s.stop_seconds) / 60) AS fpm FROM setups s JOIN shifts sh ON sh.production_date = s.production_date AND sh.shift = s.shift WHERE s.production_date BETWEEN ? AND ? AND s.shift = ? AND s.seconds - s.stop_seconds >= ? * 60), ranked AS (SELECT *, ntile(5) OVER (PARTITION BY grade, slice ORDER BY fpm DESC) AS fifth FROM base) SELECT grade, slice, max(target) AS target, count(*) AS setups, sum(feet) AS feet, sum(gross) AS gross, sum(run_min) AS run_min, quantile_cont(fpm, 0.5) AS median_fpm, sum(CASE WHEN fifth = 1 THEN feet END) AS best_feet, sum(CASE WHEN fifth = 1 THEN run_min END) AS best_run_min, sum(CASE WHEN fifth = 1 THEN rejects END) AS best_rejects, sum(CASE WHEN fifth = 1 THEN gross END) AS best_gross, sum(CASE WHEN fifth > 1 THEN rejects END) AS rest_rejects, sum(CASE WHEN fifth > 1 THEN gross END) AS rest_gross FROM ranked GROUP BY grade, slice ORDER BY grade, slice;
SELECT count(*) AS short FROM setups WHERE production_date BETWEEN ? AND ? AND shift = ? AND seconds - stop_seconds < ? * 60

